/* ============================================================
   SWORD ART ONLINE 3D — AINCRAD ASCENSION
   Fan-made interface + cinematic presentation
   ============================================================ */

@font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-400.ttf') format('truetype'); font-weight:400; font-display:swap; }
@font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-600.ttf') format('truetype'); font-weight:600; font-display:swap; }
@font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-700.ttf') format('truetype'); font-weight:700; font-display:swap; }
@font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-800.ttf') format('truetype'); font-weight:800; font-display:swap; }
@font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-900.ttf') format('truetype'); font-weight:900; font-display:swap; }
@font-face { font-family:'Rajdhani'; src:url('/fonts/Rajdhani-300.ttf') format('truetype'); font-weight:300; font-display:swap; }
@font-face { font-family:'Rajdhani'; src:url('/fonts/Rajdhani-400.ttf') format('truetype'); font-weight:400; font-display:swap; }
@font-face { font-family:'Rajdhani'; src:url('/fonts/Rajdhani-500.ttf') format('truetype'); font-weight:500; font-display:swap; }
@font-face { font-family:'Rajdhani'; src:url('/fonts/Rajdhani-600.ttf') format('truetype'); font-weight:600; font-display:swap; }
@font-face { font-family:'Rajdhani'; src:url('/fonts/Rajdhani-700.ttf') format('truetype'); font-weight:700; font-display:swap; }

:root {
  --cyan: #6ef4ff;
  --cyan-soft: #a7f8ff;
  --cyan-deep: #20a6c7;
  --rose: #ff5b83;
  --rose-soft: #ff9ab5;
  --gold: #f7cb7a;
  --ink: #05070f;
  --panel: rgba(8, 13, 27, .72);
  --line: rgba(140, 231, 255, .28);
  --text: #e9faff;
  --muted: #91a7b9;
  --display: 'Orbitron', 'Arial Black', sans-serif;
  --body: 'Rajdhani', 'Trebuchet MS', sans-serif;
}

* { box-sizing: border-box; }
html, body { margin:0; width:100%; height:100%; overflow:hidden; background:#05070f; color:var(--text); font-family:var(--body); }
body { -webkit-user-select:none; user-select:none; -webkit-tap-highlight-color:transparent; }
button { font-family:var(--body); cursor:pointer; border:0; background:none; color:inherit; }
canvas { display:block; }
#app { position:fixed; inset:0; z-index:0; }
#app canvas { width:100%; height:100%; outline:none; }

.hidden { display:none !important; }
.screen { position:fixed; inset:0; z-index:40; }

.letterbox { position:fixed; left:0; right:0; height:0; background:#020308; z-index:60; pointer-events:none; transition:height 1.1s cubic-bezier(.7,0,.2,1); }
#letterbox-top { top:0; } #letterbox-bottom { bottom:0; }
body.cinematic .letterbox { height:6vh; }

/* ---------- Loader ---------- */
#loader { z-index:100; display:flex; flex-direction:column; align-items:center; justify-content:center; background:radial-gradient(ellipse at 50% 46%, #10233c 0%, #060a16 42%, #02040a 100%); transition:opacity .8s ease, visibility .8s; }
#loader.done { opacity:0; visibility:hidden; }
.loader-mark { width:88px; height:88px; margin-bottom:24px; filter:drop-shadow(0 0 18px rgba(110,244,255,.6)); }
.loader-mark svg { width:100%; height:100%; overflow:visible; }
.mark-ring { fill:none; stroke:url(#g); stroke:#6ef4ff; stroke-width:1.4; opacity:.75; stroke-dasharray:220; stroke-dashoffset:0; animation:markPulse 2.4s ease-in-out infinite; }
.mark-sword,.mark-guard { fill:none; stroke:#dffcff; stroke-width:1.4; stroke-linejoin:round; }
.loader-wordmark { font-family:var(--display); font-size:24px; font-weight:800; letter-spacing:.38em; margin-left:.38em; }
.loader-wordmark span { color:var(--cyan); font-weight:400; }
.loader-sub { margin-top:10px; color:#66849a; font-size:11px; letter-spacing:.32em; font-weight:600; }
.loader-track { width:280px; height:2px; margin-top:32px; background:rgba(110,244,255,.12); position:relative; overflow:hidden; }
#loader-bar { height:100%; width:0%; background:linear-gradient(90deg, #1e8ba5, var(--cyan)); box-shadow:0 0 12px var(--cyan); transition:width .25s ease; }
.loader-status { width:280px; display:flex; justify-content:space-between; margin-top:12px; font-size:10px; letter-spacing:.18em; color:#66849a; font-weight:600; }
#loader-percent { color:var(--cyan); }
@keyframes markPulse { 0%,100%{opacity:.45} 50%{opacity:1} }

/* ---------- Title ---------- */
#title-screen { background:linear-gradient(90deg, rgba(3,6,14,.88) 0%, rgba(3,6,14,.64) 32%, rgba(3,6,14,.04) 64%, rgba(3,6,14,.25) 100%); }
.title-vignette { position:absolute; inset:0; background:radial-gradient(ellipse at 60% 42%, transparent 0%, transparent 45%, rgba(2,5,12,.45) 100%), linear-gradient(0deg, rgba(2,5,12,.7), transparent 30%); pointer-events:none; }
.title-left { position:absolute; left:clamp(28px, 7vw, 126px); top:50%; transform:translateY(-51%); width:min(760px, 55vw); z-index:2; }
.title-kicker { display:flex; align-items:center; gap:13px; color:#a9d6e6; font-size:12px; font-weight:600; letter-spacing:.3em; margin-bottom:22px; opacity:0; animation:titleIn .9s .15s ease forwards; }
.title-kicker span { display:block; width:38px; height:1px; background:var(--cyan); box-shadow:0 0 8px var(--cyan); }
.title-kicker b { color:var(--cyan); font-weight:400; }
.title-logo { margin:0; font-family:var(--display); font-weight:900; line-height:.82; letter-spacing:-.055em; display:flex; flex-direction:column; filter:drop-shadow(0 8px 30px rgba(0,0,0,.55)); }
.title-sword, .title-art { color:#f3feff; text-shadow:0 0 48px rgba(164,246,255,.18); opacity:0; animation:logoIn 1s .28s cubic-bezier(.2,.8,.2,1) forwards; }
.title-art { margin-left:.02em; }
.title-online { color:transparent; -webkit-text-stroke:2px var(--cyan); font-weight:400; letter-spacing:.02em; font-size:.55em; margin-top:.22em; opacity:0; animation:logoIn 1.2s .55s cubic-bezier(.2,.8,.2,1) forwards; text-shadow:0 0 30px rgba(110,244,255,.3); }
.title-sub { margin-top:22px; font-family:var(--display); font-size:clamp(13px,1.5vw,19px); letter-spacing:.58em; color:#9db7c7; font-weight:400; opacity:0; animation:titleIn .9s .8s ease forwards; }
.title-sub span { color:var(--gold); font-weight:700; }
.title-rule { width:0; height:1px; margin:27px 0 23px; background:linear-gradient(90deg, var(--cyan), rgba(110,244,255,0)); box-shadow:0 0 8px rgba(110,244,255,.4); animation:ruleIn 1.2s 1s cubic-bezier(.2,.8,.2,1) forwards; }
.title-copy { margin:0 0 32px; font-size:clamp(19px,2.1vw,27px); line-height:1.25; font-weight:300; color:#d6edf5; letter-spacing:.045em; opacity:0; animation:titleIn .9s 1.1s ease forwards; }
.title-copy br + * { color:var(--gold); }
.title-actions { display:flex; align-items:center; gap:18px; opacity:0; animation:titleIn .9s 1.3s ease forwards; }
