.btn-primary:hover { background:linear-gradient(100deg, rgba(32,176,205,.56), rgba(20,90,116,.42)); box-shadow:inset 0 0 38px rgba(110,244,255,.15), 0 0 48px rgba(54,220,246,.25); transform:translateY(-2px); }
.btn-primary:active { transform:translateY(0); }
.btn-primary:disabled { opacity:.45; cursor:wait; }
