.btn-secondary:hover { color:#eaffff; border-color:rgba(110,244,255,.5); background:rgba(20,48,65,.38); }
.btn-primary.compact { height:54px; min-width:220px; font-size:11px; justify-content:center; }
.title-meta { display:flex; gap:42px; margin-top:43px; opacity:0; animation:titleIn .9s 1.5s ease forwards; }
.title-meta div { display:flex; flex-direction:column; gap:5px; }
.title-meta span { color:#587488; font-size:9px; font-weight:700; letter-spacing:.26em; }
.title-meta b { color:#c7e4ed; font-size:12px; letter-spacing:.17em; font-weight:600; }
.title-meta div:last-child b { color:var(--gold); }
.title-right { position:absolute; right:clamp(26px,5.4vw,90px); top:clamp(28px,5vw,64px); z-index:3; display:flex; flex-direction:column; align-items:flex-end; gap:18px; }
.world-status { width:220px; padding:17px 18px 15px; border:1px solid rgba(117,219,240,.2); background:linear-gradient(140deg, rgba(8,17,31,.72), rgba(8,17,31,.2)); backdrop-filter:blur(7px); clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%); }
.world-status-head { display:flex; align-items:center; gap:7px; color:#7795a8; font-size:9px; font-weight:700; letter-spacing:.2em; padding-bottom:12px; border-bottom:1px solid rgba(110,244,255,.12); margin-bottom:12px; }
.world-status-head b { margin-left:auto; color:var(--cyan); font-size:9px; }
.pulse-dot { width:5px; height:5px; background:var(--cyan); border-radius:50%; box-shadow:0 0 7px var(--cyan); animation:blink 2s infinite; }
.world-stat { display:flex; align-items:center; gap:8px; height:21px; color:#607c8d; font-size:8px; font-weight:700; letter-spacing:.14em; }
