.world-bar { flex:1; height:2px; background:rgba(110,244,255,.12); }
.world-bar i { display:block; height:100%; background:linear-gradient(90deg, #248ca4, var(--cyan)); box-shadow:0 0 5px rgba(110,244,255,.4); }
.world-bar.gate i { background:linear-gradient(90deg,#a48436,var(--gold)); }
.title-credit { color:#60798a; font-size:8px; letter-spacing:.26em; }
.title-bottom { position:absolute; left:clamp(28px,7vw,126px); right:clamp(26px,5.4vw,90px); bottom:clamp(22px,4vh,42px); display:flex; gap:14px; color:#597182; font-size:8px; font-weight:700; letter-spacing:.19em; opacity:0; animation:titleIn 1s 1.7s ease forwards; }
.title-sep { color:rgba(110,244,255,.5); }
@keyframes titleIn { from{opacity:0; transform:translateY(14px)} to{opacity:1; transform:none} }
@keyframes logoIn { from{opacity:0; transform:translateY(28px); filter:blur(8px)} to{opacity:1; transform:none; filter:blur(0)} }
@keyframes ruleIn { to{width:min(390px,80%)} }
@keyframes blink { 0%,100%{opacity:1} 50%{opacity:.3} }
