/* ---------- HUD base ---------- */
#hud { position:fixed; inset:0; z-index:20; pointer-events:none; font-family:var(--body); }
#hud::before { content:''; position:absolute; inset:0; background:radial-gradient(ellipse at 50% 50%, transparent 60%, rgba(2,5,12,.35) 100%); pointer-events:none; }
.hud-corner { position:absolute; width:34px; height:34px; border-color:rgba(110,244,255,.36); border-style:solid; opacity:.75; }
.hud-corner-tl { left:22px; top:22px; border-width:1px 0 0 1px; }
.hud-corner-tr { right:22px; top:22px; border-width:1px 1px 0 0; }
.hud-corner-bl { left:22px; bottom:22px; border-width:0 0 1px 1px; }
.hud-corner-br { right:22px; bottom:22px; border-width:0 1px 1px 0; }

.player-panel { position:absolute; left:clamp(24px,3vw,52px); top:clamp(25px,4vh,49px); display:flex; gap:13px; filter:drop-shadow(0 5px 22px rgba(0,0,0,.45)); animation:hudIn .8s ease both; }
.player-avatar { position:relative; width:72px; height:72px; flex:none; background:#080d17; border:1px solid rgba(110,244,255,.45); clip-path:polygon(0 0,100% 0,100% calc(100% - 13px),calc(100% - 13px) 100%,0 100%); overflow:hidden; }
#portrait { width:100%; height:100%; }
.avatar-ring { position:absolute; inset:4px; border:1px solid rgba(110,244,255,.12); pointer-events:none; clip-path:polygon(0 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%); }
.avatar-level { position:absolute; right:3px; bottom:2px; color:var(--gold); font-family:var(--display); font-size:8px; font-weight:700; background:rgba(3,8,15,.8); padding:2px 4px; border-left:1px solid rgba(247,203,122,.35); }
.player-vitals { width:min(320px,30vw); padding-top:1px; }
.player-name-row { display:flex; align-items:baseline; gap:11px; margin-bottom:4px; }
.player-name { font-family:var(--display); font-size:15px; font-weight:700; letter-spacing:.2em; color:#f2feff; text-shadow:0 0 18px rgba(110,244,255,.4); }
.player-class { color:#748e9e; font-size:8px; font-weight:700; letter-spacing:.18em; white-space:nowrap; }
.bar { position:relative; height:15px; background:rgba(5,10,19,.72); border:1px solid rgba(115,203,220,.22); overflow:hidden; clip-path:polygon(0 0,100% 0,calc(100% - 6px) 100%,0 100%); }
.hp-bar { height:16px; margin-bottom:4px; }
.bar-fill { position:absolute; left:0; top:0; bottom:0; width:100%; background:linear-gradient(90deg, #a1253e, #ff5679 62%, #ffa0b5); box-shadow:0 0 12px rgba(255,75,110,.25); transition:width .2s ease; }
.stamina-bar { width:72%; height:5px; background:rgba(5,10,19,.8); }
.stamina-bar .bar-fill { width:100%; background:linear-gradient(90deg, #177c8e, var(--cyan)); }
.bar-sheen { position:absolute; inset:0; background:linear-gradient(180deg, rgba(255,255,255,.18), transparent 48%, rgba(0,0,0,.16)); }
.bar span { position:absolute; inset:0; padding:0 9px; font-size:9px; line-height:16px; display:flex; align-items:center; justify-content:flex-end; color:rgba(255,255,255,.86); text-shadow:0 1px 2px #000; font-weight:600; letter-spacing:.1em; }
.stamina-bar span { justify-content:flex-start; line-height:5px; font-size:7px; color:#82b2c0; padding-left:7px; letter-spacing:.18em; }

/* Wave panel */
.wave-panel { position:absolute; top:clamp(28px,4.5vh,55px); left:50%; transform:translateX(-50%); min-width:280px; text-align:center; animation:hudIn .8s .15s ease both; }
.wave-label { color:#6c8798; font-size:8px; font-weight:700; letter-spacing:.32em; margin-bottom:5px; }
.wave-main { display:flex; align-items:center; justify-content:center; gap:15px; }
#wave-number { font-family:var(--display); font-size:19px; font-weight:700; letter-spacing:.16em; color:#effdff; text-shadow:0 0 16px rgba(110,244,255,.3); }
#enemy-count { color:var(--rose-soft); font-size:9px; letter-spacing:.2em; font-weight:700; border-left:1px solid rgba(255,120,150,.24); padding-left:14px; }
.wave-timer { margin-top:8px; display:flex; align-items:center; justify-content:center; gap:8px; color:#7894a5; }
.wave-timer span { font-family:var(--display); font-size:10px; letter-spacing:.13em; color:#c3e7ef; }
.wave-timer i { font-style:normal; font-size:7px; letter-spacing:.23em; }
.wave-panel::before, .wave-panel::after { content:''; position:absolute; top:27px; width:54px; height:1px; background:linear-gradient(90deg,transparent,rgba(110,244,255,.35)); }
.wave-panel::before { left:-42px; }
.wave-panel::after { right:-42px; transform:rotate(180deg); }

/* Boss */
.boss-panel { position:absolute; top:clamp(100px,13vh,132px); left:50%; transform:translateX(-50%); width:min(680px,62vw); text-align:center; animation:bossIn .7s cubic-bezier(.2,.8,.2,1) both; }
.boss-title { display:flex; justify-content:center; align-items:baseline; gap:14px; margin-bottom:7px; }
.boss-title span { color:#bc7b8b; font-size:8px; font-weight:700; letter-spacing:.3em; }
.boss-title b { font-family:var(--display); font-size:13px; letter-spacing:.22em; color:#ffe9ec; text-shadow:0 0 20px rgba(255,60,95,.35); }
.boss-title i { font-size:8px; font-style:normal; letter-spacing:.15em; color:#c18493; }
.boss-bar { position:relative; height:12px; background:rgba(12,4,9,.8); border:1px solid rgba(255,110,140,.36); overflow:hidden; transform:skewX(-18deg); }
#boss-fill { position:absolute; left:0; top:0; bottom:0; width:100%; background:linear-gradient(90deg, #5d0d25, #d02549 55%, #ff6a8b); box-shadow:0 0 17px rgba(255,63,102,.45); transition:width .18s ease; }
#boss-damage { position:absolute; top:0; bottom:0; right:0; width:0%; background:rgba(255,221,154,.7); transition:width .65s ease .2s; }
.boss-bar-ticks { position:absolute; inset:0; background:repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(8,3,10,.5) calc(10% - 1px), rgba(8,3,10,.5) 10%); }
.boss-phase { display:flex; justify-content:space-between; padding:5px 4px 0; color:#a36778; font-size:8px; font-weight:700; letter-spacing:.2em; }
#boss-phase-label { color:var(--rose-soft); }
.boss-panel.phase-two .boss-title b { color:#ffd6dd; text-shadow:0 0 26px rgba(255,40,85,.55); }
.boss-panel.phase-two #boss-fill { background:linear-gradient(90deg,#6a041b,#ff1744 55%,#ff9caf); }

/* Radar */
.radar-panel { position:absolute; right:clamp(24px,3vw,52px); top:clamp(25px,4vh,49px); width:134px; animation:hudIn .8s .2s ease both; }
.radar-head { display:flex; justify-content:space-between; color:#698596; font-size:7px; letter-spacing:.22em; font-weight:700; margin-bottom:6px; }
.radar-head b { color:var(--cyan); font-family:var(--display); font-weight:600; }
.radar-wrap { position:relative; width:134px; height:134px; border:1px solid rgba(110,244,255,.25); border-radius:50%; background:radial-gradient(circle, rgba(16,48,64,.3), rgba(4,10,18,.65) 68%, rgba(4,10,18,.2)); overflow:hidden; box-shadow:inset 0 0 26px rgba(31,142,165,.14); }
#minimap { width:100%; height:100%; }
.radar-sweep { position:absolute; inset:0; border-radius:50%; background:conic-gradient(from 0deg, transparent 0deg, rgba(110,244,255,.14) 28deg, transparent 45deg); animation:radarSpin 5s linear infinite; opacity:.7; }
.radar-cross { position:absolute; left:50%; top:8%; bottom:8%; width:1px; background:rgba(110,244,255,.13); }
.radar-cross::after { content:''; position:absolute; left:-59px; top:50%; width:119px; height:1px; background:rgba(110,244,255,.13); }
@keyframes radarSpin { to { transform:rotate(360deg) } }

.crosshair { position:absolute; left:50%; top:50%; width:16px; height:16px; transform:translate(-50%,-50%); opacity:.38; }
.crosshair i { position:absolute; background:var(--cyan); box-shadow:0 0 4px rgba(110,244,255,.5); }
.crosshair i:first-child { width:1px; height:16px; left:8px; }
.crosshair i:last-child { width:16px; height:1px; top:8px; }
.lock-reticle { position:absolute; width:50px; height:50px; margin:-25px 0 0 -25px; border:1px solid rgba(255,105,137,.8); transform:rotate(45deg); filter:drop-shadow(0 0 7px rgba(255,64,102,.6)); transition:opacity .15s; }
.lock-reticle span, .lock-reticle i { position:absolute; background:var(--rose); }
.lock-reticle span { left:50%; top:-7px; width:1px; height:12px; }
.lock-reticle i { left:-7px; top:50%; width:12px; height:1px; }
.lock-reticle b { position:absolute; inset:-6px; border:1px solid rgba(255,105,137,.2); animation:reticlePulse 1.8s ease-in-out infinite; }
@keyframes reticlePulse { 0%,100%{transform:scale(1);opacity:.25} 50%{transform:scale(1.15);opacity:.7} }

/* Combo */
.combo-panel { position:absolute; left:clamp(34px,5vw,80px); top:46%; display:flex; align-items:flex-end; gap:11px; opacity:0; transform:translateX(-20px); transition:opacity .2s, transform .2s; }
.combo-panel.show { opacity:1; transform:none; }
.combo-number { font-family:var(--display); font-size:clamp(52px,6vw,82px); font-weight:900; line-height:.8; color:#f2feff; text-shadow:0 0 30px rgba(110,244,255,.55), 3px 3px 0 rgba(26,107,130,.35); font-style:italic; }
.combo-meta { display:flex; flex-direction:column; padding-bottom:5px; }
.combo-meta b { font-family:var(--display); font-size:11px; letter-spacing:.18em; color:var(--cyan); }
.combo-meta span { font-size:8px; letter-spacing:.25em; color:#7491a1; font-weight:700; }
.combo-panel.pop .combo-number { animation:comboPop .22s ease; }
@keyframes comboPop { 50% { transform:scale(1.16) skewX(-4deg); color:#fff } }

/* Notice */
.notice { position:absolute; left:50%; top:25%; transform:translate(-50%,-50%); text-align:center; display:flex; flex-direction:column; gap:4px; opacity:0; }
.notice.show { animation:noticeAnim 2.8s ease forwards; }
.notice span { color:var(--cyan); font-size:9px; font-weight:700; letter-spacing:.5em; }
.notice b { font-family:var(--display); font-size:clamp(26px,4vw,52px); letter-spacing:.17em; font-weight:700; color:#f4feff; text-shadow:0 0 40px rgba(110,244,255,.38); line-height:1.1; }
.notice i { font-style:normal; color:#9bb8c5; font-size:10px; letter-spacing:.32em; font-weight:600; margin-top:5px; }
.notice.rose span,.notice.rose b { color:var(--rose-soft); text-shadow:0 0 35px rgba(255,50,90,.45); }
.notice.gold b { color:var(--gold); text-shadow:0 0 35px rgba(255,187,87,.4); }
@keyframes noticeAnim { 0%{opacity:0; transform:translate(-50%,-50%) scale(1.12); filter:blur(6px)} 12%{opacity:1; filter:blur(0); transform:translate(-50%,-50%) scale(1)} 70%{opacity:1} 100%{opacity:0; transform:translate(-50%,-58%) scale(1.02)} }

/* Skill */
.skill-panel { position:absolute; left:50%; bottom:clamp(26px,4vh,45px); transform:translateX(-50%); display:flex; align-items:center; gap:13px; }
.skill-orb { position:relative; width:72px; height:72px; flex:none; filter:drop-shadow(0 0 12px rgba(110,244,255,.2)); }
.skill-orb svg { width:100%; height:100%; transform:rotate(-90deg); overflow:visible; }
.orb-track { fill:rgba(5,12,22,.66); stroke:rgba(110,244,255,.2); stroke-width:2; }
.orb-progress { fill:none; stroke:url(#none); stroke:var(--cyan); stroke-width:2.5; stroke-linecap:round; stroke-dasharray:276.5; stroke-dashoffset:276.5; filter:drop-shadow(0 0 5px rgba(110,244,255,.7)); transition:stroke-dashoffset .18s ease; }
.orb-swords, .orb-cross { fill:none; stroke:#d9fbff; stroke-width:2; stroke-linejoin:round; transform:rotate(90deg); transform-origin:50px 50px; }
.orb-cross { stroke:rgba(110,244,255,.65); stroke-width:1.5; }
.skill-ready { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; color:#091018; font-family:var(--display); font-size:7px; font-weight:900; letter-spacing:.13em; background:var(--cyan); clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%); opacity:0; transform:scale(.7); transition:.25s; }
.skill-orb.ready { animation:skillGlow 1.7s ease-in-out infinite; }
.skill-orb.ready .skill-ready { opacity:1; transform:scale(1); }
.skill-orb.ready .orb-progress { stroke:#fff; }
.skill-orb.ready svg { opacity:.35; }
.skill-copy { display:flex; flex-direction:column; gap:2px; min-width:165px; }
.skill-copy span { color:#708b9b; font-size:7px; letter-spacing:.26em; font-weight:700; }
.skill-copy b { font-family:var(--display); font-size:10px; letter-spacing:.13em; color:#c4e6ed; font-weight:600; }
.skill-copy i { font-style:normal; color:#5e7e8e; font-size:8px; letter-spacing:.11em; font-weight:600; }
.skill-orb.ready + .skill-copy b { color:var(--cyan); text-shadow:0 0 15px rgba(110,244,255,.5); }
@keyframes skillGlow { 0%,100%{filter:drop-shadow(0 0 10px rgba(110,244,255,.35))} 50%{filter:drop-shadow(0 0 24px rgba(110,244,255,.85))} }

/* controls */
.controls-panel { position:absolute; right:clamp(24px,3vw,52px); bottom:clamp(26px,4vh,44px); display:grid; grid-template-columns:auto auto; gap:5px 16px; opacity:.66; animation:hudIn .8s .3s ease both; }
.controls-panel div { display:flex; align-items:center; gap:6px; justify-content:flex-end; }
.controls-panel kbd { font-family:var(--display); font-size:7px; color:#b8d5df; background:rgba(9,18,31,.7); border:1px solid rgba(120,195,214,.25); padding:3px 5px; min-width:29px; text-align:center; letter-spacing:.06em; }
.controls-panel span { color:#718d9d; font-size:7px; font-weight:700; letter-spacing:.18em; min-width:55px; }

.damage-layer { position:absolute; inset:0; overflow:hidden; }
.dmg { position:absolute; font-family:var(--display); font-weight:800; font-size:17px; color:#fff; text-shadow:0 2px 6px rgba(0,0,0,.8), 0 0 12px rgba(110,244,255,.35); animation:dmgFloat .85s cubic-bezier(.2,.7,.2,1) forwards; white-space:nowrap; }
.dmg.crit { color:var(--gold); font-size:23px; text-shadow:0 2px 7px #000, 0 0 18px rgba(255,185,70,.8); }
.dmg.player { color:var(--rose); font-size:22px; text-shadow:0 2px 7px #000, 0 0 18px rgba(255,30,70,.8); }
.dmg.heal { color:#7dffd0; font-size:15px; }
@keyframes dmgFloat { 0%{opacity:0; transform:translate(-50%,0) scale(.6)} 15%{opacity:1; transform:translate(-50%,-8px) scale(1.12)} 100%{opacity:0; transform:translate(-50%,-58px) scale(.92)} }
.hit-vignette { position:absolute; inset:0; background:radial-gradient(ellipse at 50% 50%, transparent 38%, rgba(255,25,70,.42) 100%); opacity:0; transition:opacity .1s; }
.hit-vignette.flash { animation:hurtFlash .55s ease-out; }
@keyframes hurtFlash { 0%{opacity:.9} 100%{opacity:0} }
.heal-flash { position:absolute; inset:0; background:radial-gradient(ellipse at 50% 50%, transparent 45%, rgba(72,255,190,.19) 100%); opacity:0; }
.heal-flash.flash { animation:healFlash 1s ease-out; }
@keyframes healFlash { 0%{opacity:1} 100%{opacity:0} }
.edge-glow { position:absolute; inset:0; background:linear-gradient(0deg, rgba(30,180,210,.13), transparent 19%), linear-gradient(180deg, rgba(30,180,210,.08), transparent 15%); mix-blend-mode:screen; opacity:.4; }

.enemy-labels { position:absolute; inset:0; overflow:hidden; }
.enemy-label { position:absolute; transform:translate(-50%,-100%); min-width:102px; text-align:center; transition:opacity .2s; will-change:transform; }
.enemy-label .e-name { font-size:8px; letter-spacing:.16em; font-weight:700; color:#ffc0cc; text-shadow:0 1px 5px #000; white-space:nowrap; }
.enemy-label .e-name b { color:var(--rose); font-weight:700; margin-right:5px; }
.enemy-label .e-bar { margin:4px auto 0; width:94px; height:3px; background:rgba(3,6,12,.75); border:1px solid rgba(255,110,140,.3); }
.enemy-label .e-bar i { display:block; height:100%; background:linear-gradient(90deg,#a92242,#ff6487); transition:width .15s; }
.enemy-label .e-chev { width:7px; height:7px; margin:5px auto 0; border:1px solid var(--rose); transform:rotate(45deg); opacity:.65; }
.enemy-label.locked .e-name { color:#fff; text-shadow:0 0 9px rgba(255,50,90,.9); }
.enemy-label.locked .e-chev { background:rgba(255,80,115,.5); box-shadow:0 0 8px rgba(255,50,90,.7); opacity:1; }
.enemy-label.boss .e-name { font-size:10px; color:#ffdbe1; }
.enemy-label.boss .e-bar { width:140px; height:4px; }

/* boss intro bars */
.boss-intro { position:absolute; left:50%; top:50%; transform:translate(-50%,-50%); width:min(720px,80vw); text-align:center; pointer-events:none; }
.boss-intro b { font-family:var(--display); font-size:clamp(20px,3.4vw,42px); color:#fff; letter-spacing:.18em; text-shadow:0 0 40px rgba(255,40,80,.6); }
.boss-intro span { display:block; color:var(--rose); font-size:10px; letter-spacing:.45em; margin-top:8px; }

@keyframes hudIn { from{opacity:0; transform:translateY(-10px)} to{opacity:1; transform:none} }
@keyframes bossIn { from{opacity:0; transform:translate(-50%,-12px)} to{opacity:1; transform:translate(-50%,0)} }
