8: @font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-700.ttf') format('truetype'); font-weight:700; font-display:swap; }
9: @font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-800.ttf') format('truetype'); font-weight:800; font-display:swap; }
10: @font-face { font-family:'Orbitron'; src:url('/fonts/Orbitron-900.ttf') format('truetype'); font-weight:900; font-display:swap; }
