17: :root {
18:   --cyan: #6ef4ff;
19:   --cyan-soft: #a7f8ff;
20:   --cyan-deep: #20a6c7;
21:   --rose: #ff5b83;
22:   --rose-soft: #ff9ab5;
23:   --gold: #f7cb7a;
24:   --ink: #05070f;
25:   --panel: rgba(8, 13, 27, .72);
26:   --line: rgba(140, 231, 255, .28);
27:   --text: #e9faff;
28:   --muted: #91a7b9;
29:   --display: 'Orbitron', 'Arial Black', sans-serif;
30:   --body: 'Rajdhani', 'Trebuchet MS', sans-serif;
31: }
32: 
33: * { box-sizing: border-box; }
34: html, body { margin:0; width:100%; height:100%; overflow:hidden; background:#05070f; color:var(--text); font-family:var(--body); }
35: body { -webkit-user-select:none; user-select:none; -webkit-tap-highlight-color:transparent; }
36: button { font-family:var(--body); cursor:pointer; border:0; background:none; color:inherit; }
37: canvas { display:block; }
38: #app { position:fixed; inset:0; z-index:0; }
39: #app canvas { width:100%; height:100%; outline:none; }
40: 
41: .hidden { display:none !important; }
42: .screen { position:fixed; inset:0; z-index:40; }
43: 
44: .letterbox { position:fixed; left:0; right:0; height:0; background:#020308; z-index:60; pointer-events:none; transition:height 1.1s cubic-bezier(.7,0,.2,1); }
45: #letterbox-top { top:0; } #letterbox-bottom { bottom:0; }
46: body.cinematic .letterbox { height:6vh; }
47: 
48: /* ---------- Loader ---------- */
49: #loader { z-index:100; display:flex; flex-direction:column; align-items:center; justify-content:center; background:radial-gradient(ellipse at 50% 46%, #10233c 0%, #060a16 42%, #02040a 100%); transition:opacity .8s ease, visibility .8s; }
50: #loader.done { opacity:0; visibility:hidden; }
51: .loader-mark { width:88px; height:88px; margin-bottom:24px; filter:drop-shadow(0 0 18px rgba(110,244,255,.6)); }
52: .loader-mark svg { width:100%; height:100%; overflow:visible; }
53: .mark-ring { fill:none; stroke:url(#g); stroke:#6ef4ff; stroke-width:1.4; opacity:.75; stroke-dasharray:220; stroke-dashoffset:0; animation:markPulse 2.4s ease-in-out infinite; }
54: .mark-sword,.mark-guard { fill:none; stroke:#dffcff; stroke-width:1.4; stroke-linejoin:round; }
55: .loader-wordmark { font-family:var(--display); font-size:24px; font-weight:800; letter-spacing:.38em; margin-left:.38em; }
56: .loader-wordmark span { color:var(--cyan); font-weight:400; }
57: .loader-sub { margin-top:10px; color:#66849a; font-size:11px; letter-spacing:.32em; font-weight:600; }
58: .loader-track { width:280px; height:2px; margin-top:32px; background:rgba(110,244,255,.12); position:relative; overflow:hidden; }
59: #loader-bar { height:100%; width:0%; background:linear-gradient(90deg, #1e8ba5, var(--cyan)); box-shadow:0 0 12px var(--cyan); transition:width .25s ease; }
60: .loader-status { width:280px; display:flex; justify-content:space-between; margin-top:12px; font-size:10px; letter-spacing:.18em; color:#66849a; font-weight:600; }
61: #loader-percent { color:var(--cyan); }
62: @keyframes markPulse { 0%,100%{opacity:.45} 50%{opacity:1} }
63: 
64: /* ---------- Title ---------- */
65: #title-screen { background:linear-gradient(90deg, rgba(3,6,14,.88) 0%, rgba(3,6,14,.64) 32%, rgba(3,6,14,.04) 64%, rgba(3,6,14,.25) 100%); }
66: .title-vignette { position:absolute; inset:0; background:radial-gradient(ellipse at 60% 42%, transparent 0%, transparent 45%, rgba(2,5,12,.45) 100%), linear-gradient(0deg, rgba(2,5,12,.7), transparent 30%); pointer-events:none; }
67: .title-left { position:absolute; left:clamp(28px, 7vw, 126px); top:50%; transform:translateY(-51%); width:min(760px, 55vw); z-index:2; }
68: .title-kicker { display:flex; align-items:center; gap:13px; color:#a9d6e6; font-size:12px; font-weight:600; letter-spacing:.3em; margin-bottom:22px; opacity:0; animation:titleIn .9s .15s ease forwards; }
69: .title-kicker span { display:block; width:38px; height:1px; background:var(--cyan); box-shadow:0 0 8px var(--cyan); }
70: .title-kicker b { color:var(--cyan); font-weight:400; }
71: .title-logo { margin:0; font-family:var(--display); font-weight:900; line-height:.82; letter-spacing:-.055em; display:flex; flex-direction:column; filter:drop-shadow(0 8px 30px rgba(0,0,0,.55)); }
72: .title-sword, .title-art { color:#f3feff; text-shadow:0 0 48px rgba(164,246,255,.18); opacity:0; animation:logoIn 1s .28s cubic-bezier(.2,.8,.2,1) forwards; }
73: .title-art { margin-left:.02em; }
74: .title-online { color:transparent; -webkit-text-stroke:2px var(--cyan); font-weight:400; letter-spacing:.02em; font-size:.55em; margin-top:.22em; opacity:0; animation:logoIn 1.2s .55s cubic-bezier(.2,.8,.2,1) forwards; text-shadow:0 0 30px rgba(110,244,255,.3); }
75: .title-sub { margin-top:22px; font-family:var(--display); font-size:clamp(13px,1.5vw,19px); letter-spacing:.58em; color:#9db7c7; font-weight:400; opacity:0; animation:titleIn .9s .8s ease forwards; }
76: .title-sub span { color:var(--gold); font-weight:700; }
77: .title-rule { width:0; height:1px; margin:27px 0 23px; background:linear-gradient(90deg, var(--cyan), rgba(110,244,255,0)); box-shadow:0 0 8px rgba(110,244,255,.4); animation:ruleIn 1.2s 1s cubic-bezier(.2,.8,.2,1) forwards; }
78: .title-copy { margin:0 0 32px; font-size:clamp(19px,2.1vw,27px); line-height:1.25; font-weight:300; color:#d6edf5; letter-spacing:.045em; opacity:0; animation:titleIn .9s 1.1s ease forwards; }
79: .title-copy br + * { color:var(--gold); }
80: .title-actions { display:flex; align-items:center; gap:18px; opacity:0; animation:titleIn .9s 1.3s ease forwards; }
81: .btn-primary { position:relative; display:inline-flex; align-items:center; gap:15px; min-width:250px; height:64px; padding:0 34px; background:linear-gradient(100deg, rgba(23,142,170,.38), rgba(16,64,88,.28)); border:1px solid rgba(110,244,255,.78); color:#ecfeff; font-family:var(--display); font-weight:700; font-size:13px; letter-spacing:.26em; clip-path:polygon(0 0, calc(100% - 17px) 0, 100% 17px, 100% 100%, 17px 100%, 0 calc(100% - 17px)); box-shadow:inset 0 0 30px rgba(110,244,255,.08), 0 0 34px rgba(48,205,230,.12); transition:background .25s ease, box-shadow .25s ease, transform .2s ease; overflow:hidden; }
82: .btn-primary::before { content:''; position:absolute; inset:0; background:linear-gradient(110deg, transparent 20%, rgba(211,253,255,.22) 48%, transparent 72%); transform:translateX(-120%); transition:transform .6s ease; }
83: .btn-primary:hover::before { transform:translateX(120%); }
84: .btn-primary:hover { background:linear-gradient(100deg, rgba(32,176,205,.56), rgba(20,90,116,.42)); box-shadow:inset 0 0 38px rgba(110,244,255,.15), 0 0 48px rgba(54,220,246,.25); transform:translateY(-2px); }
85: .btn-primary:active { transform:translateY(0); }
86: .btn-primary:disabled { opacity:.45; cursor:wait; }
87: .btn-glyph { color:var(--cyan); font-size:18px; }
88: .btn-label { position:relative; z-index:1; }
89: .btn-shine { position:absolute; inset:auto 0 0; height:1px; background:linear-gradient(90deg, transparent, var(--cyan), transparent); }
90: .btn-secondary { padding:15px 24px; border:1px solid rgba(160,205,220,.24); color:#a9c4d1; font-size:11px; font-weight:700; letter-spacing:.24em; background:rgba(8,14,26,.34); transition:.25s; }
91: .btn-secondary:hover { color:#eaffff; border-color:rgba(110,244,255,.5); background:rgba(20,48,65,.38); }
92: .btn-primary.compact { height:54px; min-width:220px; font-size:11px; justify-content:center; }
93: .title-meta { display:flex; gap:42px; margin-top:43px; opacity:0; animation:titleIn .9s 1.5s ease forwards; }
94: .title-meta div { display:flex; flex-direction:column; gap:5px; }
95: .title-meta span { color:#587488; font-size:9px; font-weight:700; letter-spacing:.26em; }
96: .title-meta b { color:#c7e4ed; font-size:12px; letter-spacing:.17em; font-weight:600; }
97: .title-meta div:last-child b { color:var(--gold); }
98: .title-right { position:absolute; right:clamp(26px,5.4vw,90px); top:clamp(28px,5vw,64px); z-index:3; display:flex; flex-direction:column; align-items:flex-end; gap:18px; }
99: .world-status { width:220px; padding:17px 18px 15px; border:1px solid rgba(117,219,240,.2); background:linear-gradient(140deg, rgba(8,17,31,.72), rgba(8,17,31,.2)); backdrop-filter:blur(7px); clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%); }
100: .world-status-head { display:flex; align-items:center; gap:7px; color:#7795a8; font-size:9px; font-weight:700; letter-spacing:.2em; padding-bottom:12px; border-bottom:1px solid rgba(110,244,255,.12); margin-bottom:12px; }
101: .world-status-head b { margin-left:auto; color:var(--cyan); font-size:9px; }
102: .pulse-dot { width:5px; height:5px; background:var(--cyan); border-radius:50%; box-shadow:0 0 7px var(--cyan); animation:blink 2s infinite; }
103: .world-stat { display:flex; align-items:center; gap:8px; height:21px; color:#607c8d; font-size:8px; font-weight:700; letter-spacing:.14em; }
104: .world-stat > span { width:44px; }
105: .world-stat b { width:36px; text-align:right; color:#bad6e1; font-size:9px; }
106: .world-bar { flex:1; height:2px; background:rgba(110,244,255,.12); }
107: .world-bar i { display:block; height:100%; background:linear-gradient(90deg, #248ca4, var(--cyan)); box-shadow:0 0 5px rgba(110,244,255,.4); }
108: .world-bar.gate i { background:linear-gradient(90deg,#a48436,var(--gold)); }
109: .title-credit { color:#60798a; font-size:8px; letter-spacing:.26em; }
110: .title-bottom { position:absolute; left:clamp(28px,7vw,126px); right:clamp(26px,5.4vw,90px); bottom:clamp(22px,4vh,42px); display:flex; gap:14px; color:#597182; font-size:8px; font-weight:700; letter-spacing:.19em; opacity:0; animation:titleIn 1s 1.7s ease forwards; }
111: .title-sep { color:rgba(110,244,255,.5); }
112: @keyframes titleIn { from{opacity:0; transform:translateY(14px)} to{opacity:1; transform:none} }
113: @keyframes logoIn { from{opacity:0; transform:translateY(28px); filter:blur(8px)} to{opacity:1; transform:none; filter:blur(0)} }
114: @keyframes ruleIn { to{width:min(390px,80%)} }
115: @keyframes blink { 0%,100%{opacity:1} 50%{opacity:.3} }
