117: /* ---------- HUD base ---------- */
118: #hud { position:fixed; inset:0; z-index:20; pointer-events:none; font-family:var(--body); }
119: #hud::before { content:''; position:absolute; inset:0; background:radial-gradient(ellipse at 50% 50%, transparent 60%, rgba(2,5,12,.35) 100%); pointer-events:none; }
120: .hud-corner { position:absolute; width:34px; height:34px; border-color:rgba(110,244,255,.36); border-style:solid; opacity:.75; }
121: .hud-corner-tl { left:22px; top:22px; border-width:1px 0 0 1px; }
122: .hud-corner-tr { right:22px; top:22px; border-width:1px 1px 0 0; }
123: .hud-corner-bl { left:22px; bottom:22px; border-width:0 0 1px 1px; }
124: .hud-corner-br { right:22px; bottom:22px; border-width:0 1px 1px 0; }
125: 
126: .player-panel { position:absolute; left:clamp(24px,3vw,52px); top:clamp(25px,4vh,49px); display:flex; gap:13px; filter:drop-shadow(0 5px 22px rgba(0,0,0,.45)); animation:hudIn .8s ease both; }
127: .player-avatar { position:relative; width:72px; height:72px; flex:none; background:#080d17; border:1px solid rgba(110,244,255,.45); clip-path:polygon(0 0,100% 0,100% calc(100% - 13px),calc(100% - 13px) 100%,0 100%); overflow:hidden; }
128: #portrait { width:100%; height:100%; }
129: .avatar-ring { position:absolute; inset:4px; border:1px solid rgba(110,244,255,.12); pointer-events:none; clip-path:polygon(0 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%); }
130: .avatar-level { position:absolute; right:3px; bottom:2px; color:var(--gold); font-family:var(--display); font-size:8px; font-weight:700; background:rgba(3,8,15,.8); padding:2px 4px; border-left:1px solid rgba(247,203,122,.35); }
131: .player-vitals { width:min(320px,30vw); padding-top:1px; }
132: .player-name-row { display:flex; align-items:baseline; gap:11px; margin-bottom:4px; }
133: .player-name { font-family:var(--display); font-size:15px; font-weight:700; letter-spacing:.2em; color:#f2feff; text-shadow:0 0 18px rgba(110,244,255,.4); }
134: .player-class { color:#748e9e; font-size:8px; font-weight:700; letter-spacing:.18em; white-space:nowrap; }
135: .bar { position:relative; height:15px; background:rgba(5,10,19,.72); border:1px solid rgba(115,203,220,.22); overflow:hidden; clip-path:polygon(0 0,100% 0,calc(100% - 6px) 100%,0 100%); }
136: .hp-bar { height:16px; margin-bottom:4px; }
137: .bar-fill { position:absolute; left:0; top:0; bottom:0; width:100%; background:linear-gradient(90deg, #a1253e, #ff5679 62%, #ffa0b5); box-shadow:0 0 12px rgba(255,75,110,.25); transition:width .2s ease; }
138: .stamina-bar { width:72%; height:5px; background:rgba(5,10,19,.8); }
139: .stamina-bar .bar-fill { width:100%; background:linear-gradient(90deg, #177c8e, var(--cyan)); }
140: .bar-sheen { position:absolute; inset:0; background:linear-gradient(180deg, rgba(255,255,255,.18), transparent 48%, rgba(0,0,0,.16)); }
141: .bar span { position:absolute; inset:0; padding:0 9px; font-size:9px; line-height:16px; display:flex; align-items:center; justify-content:flex-end; color:rgba(255,255,255,.86); text-shadow:0 1px 2px #000; font-weight:600; letter-spacing:.1em; }
142: .stamina-bar span { justify-content:flex-start; line-height:5px; font-size:7px; color:#82b2c0; padding-left:7px; letter-spacing:.18em; }
143: 
144: /* Wave panel */
145: .wave-panel { position:absolute; top:clamp(28px,4.5vh,55px); left:50%; transform:translateX(-50%); min-width:280px; text-align:center; animation:hudIn .8s .15s ease both; }
146: .wave-label { color:#6c8798; font-size:8px; font-weight:700; letter-spacing:.32em; margin-bottom:5px; }
147: .wave-main { display:flex; align-items:center; justify-content:center; gap:15px; }
148: #wave-number { font-family:var(--display); font-size:19px; font-weight:700; letter-spacing:.16em; color:#effdff; text-shadow:0 0 16px rgba(110,244,255,.3); }
149: #enemy-count { color:var(--rose-soft); font-size:9px; letter-spacing:.2em; font-weight:700; border-left:1px solid rgba(255,120,150,.24); padding-left:14px; }
150: .wave-timer { margin-top:8px; display:flex; align-items:center; justify-content:center; gap:8px; color:#7894a5; }
151: .wave-timer span { font-family:var(--display); font-size:10px; letter-spacing:.13em; color:#c3e7ef; }
152: .wave-timer i { font-style:normal; font-size:7px; letter-spacing:.23em; }
153: .wave-panel::before, .wave-panel::after { content:''; position:absolute; top:27px; width:54px; height:1px; background:linear-gradient(90deg,transparent,rgba(110,244,255,.35)); }
154: .wave-panel::before { left:-42px; }
155: .wave-panel::after { right:-42px; transform:rotate(180deg); }
156: 
157: /* Boss */
158: .boss-panel { position:absolute; top:clamp(100px,13vh,132px); left:50%; transform:translateX(-50%); width:min(680px,62vw); text-align:center; animation:bossIn .7s cubic-bezier(.2,.8,.2,1) both; }
159: .boss-title { display:flex; justify-content:center; align-items:baseline; gap:14px; margin-bottom:7px; }
160: .boss-title span { color:#bc7b8b; font-size:8px; font-weight:700; letter-spacing:.3em; }
161: .boss-title b { font-family:var(--display); font-size:13px; letter-spacing:.22em; color:#ffe9ec; text-shadow:0 0 20px rgba(255,60,95,.35); }
162: .boss-title i { font-size:8px; font-style:normal; letter-spacing:.15em; color:#c18493; }
163: .boss-bar { position:relative; height:12px; background:rgba(12,4,9,.8); border:1px solid rgba(255,110,140,.36); overflow:hidden; transform:skewX(-18deg); }
164: #boss-fill { position:absolute; left:0; top:0; bottom:0; width:100%; background:linear-gradient(90deg, #5d0d25, #d02549 55%, #ff6a8b); box-shadow:0 0 17px rgba(255,63,102,.45); transition:width .18s ease; }
165: #boss-damage { position:absolute; top:0; bottom:0; right:0; width:0%; background:rgba(255,221,154,.7); transition:width .65s ease .2s; }
166: .boss-bar-ticks { position:absolute; inset:0; background:repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(8,3,10,.5) calc(10% - 1px), rgba(8,3,10,.5) 10%); }
167: .boss-phase { display:flex; justify-content:space-between; padding:5px 4px 0; color:#a36778; font-size:8px; font-weight:700; letter-spacing:.2em; }
168: #boss-phase-label { color:var(--rose-soft); }
169: .boss-panel.phase-two .boss-title b { color:#ffd6dd; text-shadow:0 0 26px rgba(255,40,85,.55); }
170: .boss-panel.phase-two #boss-fill { background:linear-gradient(90deg,#6a041b,#ff1744 55%,#ff9caf); }
171: 
172: /* Radar */
173: .radar-panel { position:absolute; right:clamp(24px,3vw,52px); top:clamp(25px,4vh,49px); width:134px; animation:hudIn .8s .2s ease both; }
174: .radar-head { display:flex; justify-content:space-between; color:#698596; font-size:7px; letter-spacing:.22em; font-weight:700; margin-bottom:6px; }
175: .radar-head b { color:var(--cyan); font-family:var(--display); font-weight:600; }
176: .radar-wrap { position:relative; width:134px; height:134px; border:1px solid rgba(110,244,255,.25); border-radius:50%; background:radial-gradient(circle, rgba(16,48,64,.3), rgba(4,10,18,.65) 68%, rgba(4,10,18,.2)); overflow:hidden; box-shadow:inset 0 0 26px rgba(31,142,165,.14); }
177: #minimap { width:100%; height:100%; }
178: .radar-sweep { position:absolute; inset:0; border-radius:50%; background:conic-gradient(from 0deg, transparent 0deg, rgba(110,244,255,.14) 28deg, transparent 45deg); animation:radarSpin 5s linear infinite; opacity:.7; }
179: .radar-cross { position:absolute; left:50%; top:8%; bottom:8%; width:1px; background:rgba(110,244,255,.13); }
180: .radar-cross::after { content:''; position:absolute; left:-59px; top:50%; width:119px; height:1px; background:rgba(110,244,255,.13); }
181: @keyframes radarSpin { to { transform:rotate(360deg) } }
182: 
183: .crosshair { position:absolute; left:50%; top:50%; width:16px; height:16px; transform:translate(-50%,-50%); opacity:.38; }
184: .crosshair i { position:absolute; background:var(--cyan); box-shadow:0 0 4px rgba(110,244,255,.5); }
185: .crosshair i:first-child { width:1px; height:16px; left:8px; }
186: .crosshair i:last-child { width:16px; height:1px; top:8px; }
187: .lock-reticle { position:absolute; width:50px; height:50px; margin:-25px 0 0 -25px; border:1px solid rgba(255,105,137,.8); transform:rotate(45deg); filter:drop-shadow(0 0 7px rgba(255,64,102,.6)); transition:opacity .15s; }
188: .lock-reticle span, .lock-reticle i { position:absolute; background:var(--rose); }
189: .lock-reticle span { left:50%; top:-7px; width:1px; height:12px; }
190: .lock-reticle i { left:-7px; top:50%; width:12px; height:1px; }
191: .lock-reticle b { position:absolute; inset:-6px; border:1px solid rgba(255,105,137,.2); animation:reticlePulse 1.8s ease-in-out infinite; }
192: @keyframes reticlePulse { 0%,100%{transform:scale(1);opacity:.25} 50%{transform:scale(1.15);opacity:.7} }
193: 
194: /* Combo */
195: .combo-panel { position:absolute; left:clamp(34px,5vw,80px); top:46%; display:flex; align-items:flex-end; gap:11px; opacity:0; transform:translateX(-20px); transition:opacity .2s, transform .2s; }
196: .combo-panel.show { opacity:1; transform:none; }
197: .combo-number { font-family:var(--display); font-size:clamp(52px,6vw,82px); font-weight:900; line-height:.8; color:#f2feff; text-shadow:0 0 30px rgba(110,244,255,.55), 3px 3px 0 rgba(26,107,130,.35); font-style:italic; }
198: .combo-meta { display:flex; flex-direction:column; padding-bottom:5px; }
