.end-rank b { color:var(--gold); font:900 34px var(--display); text-shadow:0 0 24px rgba(247,203,122,.35); }
.end-rays { position:absolute; inset:-30%; pointer-events:none; opacity:.2; background:repeating-conic-gradient(from 0deg at 50% 50%,rgba(110,244,255,.12) 0deg,transparent 7deg,transparent 15deg); animation:radarSpin 40s linear infinite; }
