+.end-rank b { color:var(--gold); font:900 34px var(--display); text-shadow:0 0 24px rgba(247,203,122,.35); }
+.end-rays { position:absolute; inset:-30%; pointer-events:none; opacity:.2; background:repeating-conic-gradient(from 0deg at 50% 50%,rgba(110,244,255,.12) 0deg,transparent 7deg,transparent 15deg); animation:radarSpin 40s linear infinite; }
+.toast { position:fixed; z-index:70; left:50%; top:20px; transform:translateX(-50%); display:flex; gap:12px; align-items:center; padding:11px 18px; border:1px solid rgba(110,244,255,.35); background:rgba(5,14,25,.92); box-shadow:0 8px 30px #0008; font-size:10px; letter-spacing:.15em; }
+.toast span { width:6px; height:6px; border-radius:50%; background:var(--cyan); box-shadow:0 0 9px var(--cyan); }
+.toast b { color:#dffaff; }
+
+/* ---------- Touch controls / responsive ---------- */
+.touch-ui { display:none; position:absolute; inset:0; pointer-events:none; }
+.joystick { position:absolute; left:24px; bottom:34px; width:124px; height:124px; pointer-events:auto; touch-action:none; }
+.joystick-ring { position:absolute; inset:0; border:1px solid rgba(160,230,245,.3); border-radius:50%; background:rgba(7,18,30,.26); box-shadow:inset 0 0 22px rgba(110,244,255,.08); }
+.joystick-knob { position:absolute; left:50%; top:50%; width:48px; height:48px; margin:-24px; border:1px solid rgba(110,244,255,.6); border-radius:50%; background:rgba(32,166,199,.3); box-shadow:0 0 18px rgba(110,244,255,.2); }
+.touch-actions { position:absolute; right:22px; bottom:30px; width:180px; height:155px; pointer-events:none; }
+.touch-btn { position:absolute; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; border:1px solid rgba(110,244,255,.43); border-radius:50%; background:rgba(5,15,27,.62); box-shadow:inset 0 0 18px rgba(110,244,255,.1); pointer-events:auto; touch-action:manipulation; }
+.touch-btn span { font-size:19px; color:var(--cyan); }
+.touch-btn b { font-size:7px; letter-spacing:.12em; }
+.touch-btn.attack { width:72px; height:72px; right:0; bottom:0; border-color:rgba(255,111,143,.65); background:rgba(66,13,31,.65); }
+.touch-btn.attack span { color:#ff7998; }
+.touch-btn.dash { width:54px; height:54px; left:6px; bottom:3px; }
+.touch-btn.skill { width:55px; height:55px; right:49px; top:0; }
+.touch-look { position:absolute; right:0; top:0; width:48%; height:58%; pointer-events:auto; touch-action:none; }
+@media (pointer:coarse) { .touch-ui { display:block; } .controls-panel { display:none; } }
+@media (max-width:760px) {
+  .title-left { left:7vw; top:47%; width:80vw; }
+  .title-sword,.title-art { font-size:clamp(50px,13vw,100px); }
+  .title-online { font-size:clamp(25px,7vw,46px); }
+  .title-kicker { font-size:9px; letter-spacing:.2em; margin-bottom:15px; }
+  .title-sub { font-size:12px; letter-spacing:.35em; margin-top:16px; }
+  .title-copy { font-size:18px; margin-bottom:22px; }
+  .title-actions { gap:9px; flex-wrap:wrap; }
+  .btn-primary { min-width:205px; height:56px; padding:0 22px; font-size:11px; }
+  .btn-secondary { padding:14px 15px; font-size:9px; }
+  .title-meta { gap:22px; margin-top:28px; }
+  .title-right { right:5vw; top:20px; }
+  .world-status { width:180px; padding:11px 12px; }
+  .title-credit { display:none; }
+  .title-bottom { left:7vw; font-size:7px; flex-wrap:wrap; gap:7px; }
+  .player-panel { left:14px; top:16px; gap:8px; }
+  .player-avatar { width:48px; height:48px; }
+  .player-vitals { width:min(220px,48vw); }
+  .player-name { font-size:11px; }
+  .player-class { display:none; }
+  .wave-panel { top:80px; min-width:210px; }
+  .wave-panel::before,.wave-panel::after { display:none; }
+  .radar-panel { right:13px; top:16px; width:84px; }
+  .radar-wrap { width:84px; height:84px; }
+  .radar-head { font-size:6px; }
+  .boss-panel { top:140px; width:84vw; }
+  .skill-panel { bottom:18px; left:50%; gap:7px; }
+  .skill-orb { width:52px; height:52px; }
+  .skill-copy { min-width:120px; }
+  .skill-copy b { font-size:8px; }
+  .skill-copy span,.skill-copy i { font-size:6px; }
+  .combo-panel { left:24px; top:40%; }
+  .notice { top:31%; }
+  .hud-corner { width:20px; height:20px; }
+  .hud-corner-tl { left:8px; top:8px; } .hud-corner-tr { right:8px; top:8px; }
+  .hud-corner-bl { left:8px; bottom:8px; } .hud-corner-br { right:8px; bottom:8px; }
+}
+@media (max-width:480px) {
+  .title-right { top:14px; }
+  .world-status { width:150px; }
+  .world-stat > span { width:38px; }
+  .world-stat b { width:32px; }
+  .title-left { top:49%; }
+  .title-meta { gap:15px; }
+  .title-meta span { font-size:7px; }
+  .title-meta b { font-size:9px; }
+  .title-bottom { max-width:86vw; }
+  .title-bottom span:nth-of-type(2),.title-bottom span:nth-of-type(3),.title-bottom span:nth-of-type(4) { display:none; }
+  .player-avatar { display:none; }
+  .player-vitals { width:42vw; }
+  .radar-panel { transform:scale(.82); transform-origin:top right; }
+  .wave-panel { top:73px; }
+  .wave-label { font-size:7px; }
+  .wave-timer { display:none; }
+  .howto-grid { grid-template-columns:1fr; gap:8px; max-height:56vh; overflow:auto; }
+  .modal-card { padding:32px 20px; }
+  .howto-grid > div { padding:9px 12px; }
+  .howto-grid p { font-size:12px; }
+  .end-stats { grid-template-columns:repeat(2,1fr); gap:14px; }
+  .joystick { width:100px; height:100px; left:16px; bottom:20px; }
+  .joystick-knob { width:40px; height:40px; margin:-20px; }
+  .touch-actions { right:10px; bottom:15px; transform:scale(.88); transform-origin:bottom right; }
+}
+@media (max-height:620px) and (min-width:761px) {
+  .title-left { top:49%; transform:translateY(-50%) scale(.82); transform-origin:left center; }
+  .title-meta { margin-top:20px; }
+  .world-status { padding:11px 14px; }
+  .radar-panel { transform:scale(.82); transform-origin:top right; }
+}

