import * as THREE from 'three';
import './style.css';

const $ = (id) => document.getElementById(id);
const ui = Object.fromEntries(['loader','loader-bar','loader-percent','loader-status','title-screen','start-btn','howto-btn','howto-screen','howto-close','hud','pause-screen','resume-btn','restart-btn','pause-wave','pause-time','end-screen','end-title','end-kicker','end-copy','end-time','end-combo','end-damage','end-hits','end-rank','end-btn','hp-fill','hp-text','stamina-fill','wave-number','enemy-count','run-timer','boss-panel','boss-fill','boss-hp-text','boss-phase-label','skill-orb','skill-ring','skill-hint','combo-panel','combo-number','notice','notice-kicker','notice-text','notice-sub','damage-layer','hit-vignette','heal-flash','enemy-labels','lock-reticle','crosshair','minimap','portrait','joystick','joystick-knob','touch-attack','touch-dash','touch-skill','toast'].map(id=>[id,$(id)]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x91b6c8); scene.fog=new THREE.Fog(0x91b6c8,28,95);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12;
$('app').appendChild(renderer.domElement); renderer.domElement.tabIndex=0;
scene.add(new THREE.HemisphereLight(0xd9f4ff,0x354152,2.1));
const sun=new THREE.DirectionalLight(0xffe6c6,3.2); sun.position.set(-12,23,10); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-35; sun.shadow.camera.right=35; sun.shadow.camera.top=35; sun.shadow.camera.bottom=-35; scene.add(sun);
const fill=new THREE.PointLight(0x55cbed,32,55); fill.position.set(13,10,-10); scene.add(fill);
const mats={stone:new THREE.MeshStandardMaterial({color:0x718493,roughness:.78}),dark:new THREE.MeshStandardMaterial({color:0x263744,roughness:.56}),gold:new THREE.MeshStandardMaterial({color:0xd9b776,metalness:.65,roughness:.28}),cyan:new THREE.MeshStandardMaterial({color:0x75edff,emissive:0x0b7189,emissiveIntensity:1.8}),black:new THREE.MeshStandardMaterial({color:0x121923,roughness:.45}),skin:new THREE.MeshStandardMaterial({color:0xe5bd9d}),red:new THREE.MeshStandardMaterial({color:0xa93248,roughness:.46}),white:new THREE.MeshStandardMaterial({color:0xdde8e8,roughness:.5})};
const mat=(color,emissive=0)=>new THREE.MeshStandardMaterial({color,roughness:.45,metalness:.25,emissive,emissiveIntensity:emissive?1:0});
function box(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function cylinder(parent,r1,r2,h,x,y,z,material,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
function makeArena(){
 const floor=new THREE.Mesh(new THREE.CircleGeometry(27,72),new THREE.MeshStandardMaterial({color:0x788b91,roughness:.86})); floor.rotation.x=-Math.PI/2; floor.position.y=-.08; floor.receiveShadow=true; scene.add(floor);
 const outer=new THREE.Mesh(new THREE.RingGeometry(26.5,28,72),mats.gold); outer.rotation.x=-Math.PI/2; outer.position.y=.02; scene.add(outer);
 for(let r=5;r<=25;r+=5){const ring=new THREE.Mesh(new THREE.RingGeometry(r-.035,r+.035,72),new THREE.MeshBasicMaterial({color:r===15?0x5ba6b7:0xd0c29e,transparent:true,opacity:.38}));ring.rotation.x=-Math.PI/2;ring.position.y=.01;scene.add(ring);}
 for(let i=0;i<24;i++){const a=i/24*Math.PI*2;const p=new THREE.Group();p.position.set(Math.cos(a)*25,0,Math.sin(a)*25);p.rotation.y=-a;scene.add(p);cylinder(p,.64,.78,7,0,3.5,0,mats.stone,8);cylinder(p,.9,.9,.25,0,6.9,0,mats.gold,8);box(p,0,7.35,0,.18,.65,.18,mats.gold);}
 // distant Aincrad skyline and floating cliffs
 for(let i=0;i<13;i++){const a=i/13*Math.PI*2;const x=Math.cos(a)*47,z=Math.sin(a)*47;const h=7+(i*7%13);box(scene,x,h/2,z,4,h,4,i%3?mats.dark:mats.stone);const roof=new THREE.Mesh(new THREE.ConeGeometry(3.2,4,4),i%2?mats.dark:mats.gold);roof.position.set(x,h+2,z);roof.rotation.y=Math.PI/4;scene.add(roof);}
 const skyRing=new THREE.Mesh(new THREE.TorusGeometry(42,.16,8,120),new THREE.MeshBasicMaterial({color:0x8feaff,transparent:true,opacity:.45}));skyRing.position.y=35;skyRing.rotation.x=Math.PI/2.5;scene.add(skyRing);
 for(let i=0;i<18;i++){const a=i*2.4;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(1.4+(i%3)*.65,0),mats.dark);rock.position.set(Math.cos(a)* (30+(i%4)*4),10+(i*7%16),Math.sin(a)*(32+(i%4)*4));rock.scale.y=.45;rock.rotation.set(a,.4,a*.3);scene.add(rock);}
 const gate=new THREE.Group();gate.position.set(0,0,-24);scene.add(gate);for(const x of [-3.1,3.1])box(gate,x,4,0,.55,8,.7,mats.gold);const arch=new THREE.Mesh(new THREE.TorusGeometry(3.15,.22,10,32,Math.PI),mats.gold);arch.position.y=7.6;arch.rotation.z=Math.PI;gate.add(arch);const portal=new THREE.Mesh(new THREE.PlaneGeometry(5.5,6.8),new THREE.MeshBasicMaterial({color:0x44d9f4,transparent:true,opacity:.18,side:THREE.DoubleSide}));portal.position.set(0,3.8,0);gate.add(portal);
}
makeArena();
function makeHumanoid({player=false,boss=false}={}){
 const g=new THREE.Group();const scale=boss?1.65:1;g.scale.setScalar(scale);
 const tunic=player?mats.black:(boss?mats.dark:mats.red), metal=player?mats.white:(boss?mats.gold:mats.dark);
 box(g,0,1.15,0,.72,.95,.42,tunic); cylinder(g,.25,.3,.2,0,1.72,0,mats.skin,10);
 // cape
 if(player){const cape=box(g,0,1.02,.29,.68,.9,.08,mat(0x121c2c));cape.rotation.x=-.14;}
 for(const x of [-.47,.47]){cylinder(g,.13,.16,.57,x,1.14,0,metal);box(g,x,.78,0,.23,.49,.25,tunic);cylinder(g,.095,.12,.48,x,.35,0,metal);}
 // hair / helm
 if(player){const hair=new THREE.Mesh(new THREE.SphereGeometry(.27,12,10),mat(0x10151c));hair.position.set(0,1.98,-.02);hair.scale.set(1,1.05,.86);g.add(hair);box(g,0,1.78,-.24,.42,.18,.12,mat(0x0d1117));}
 else {const helm=new THREE.Mesh(new THREE.IcosahedronGeometry(.27,1),boss?mats.gold:mats.dark);helm.position.y=1.97;g.add(helm);box(g,0,1.79,-.23,.42,.12,.08,mats.red);}
 // sword mesh local aligned vertical with blade extending forward
 for(const s of [-1,1]){const blade=box(g,s*.52,1.1,-.28,.075,.85,.045,player?mats.white:(boss?mats.gold:mats.red));blade.rotation.z=s*.16;box(g,s*.52,.66,-.28,.28,.07,.08,mats.gold);}
 g.userData.swing=0;return g;
}
const player={group:makeHumanoid({player:true}),hp:100,maxHp:100,stamina:100,speed:7.5,invuln:0,attackCd:0,combo:0,comboTime:0,charge:0,dashCd:0};scene.add(player.group);player.group.position.set(0,0,6);
const enemies=[];let currentWave=0,boss=null,playing=false,paused=false,elapsed=0,damageDone=0,hitsTaken=0,maxCombo=0,lockTarget=null,noticeTimer=0,toastTimer=0;
const keys=new Set();let pointerLocked=false,dragLook=false,lastPointer={x:0,y:0},cameraYaw=0,cameraPitch=.12;
const joystick={active:false,id:null,x:0,y:0};
function createEnemy(kind='mob',angle=Math.random()*Math.PI*2){const isBoss=kind==='boss';const group=makeHumanoid({boss:isBoss});const radius=isBoss?14:10+Math.random()*7;group.position.set(Math.sin(angle)*radius,0,Math.cos(angle)*radius);scene.add(group);const enemy={group,kind,hp:isBoss?700:85,maxHp:isBoss?700:85,attack:0,stun:0,flash:0,phase:1,dead:false,angle:Math.random()*6};enemies.push(enemy);if(isBoss)boss=enemy;makeEnemyLabel(enemy);return enemy;}
function makeEnemyLabel(e){const div=document.createElement('div');div.className='enemy-label'+(e.kind==='boss'?' boss':'');div.innerHTML=`<div class="e-name"><b>◆</b>${e.kind==='boss'?'AINCRAD WARDEN':'FLOOR GUARDIAN'}</div><div class="e-bar"><i></i></div><div class="e-chev"></div>`;ui['enemy-labels'].appendChild(div);e.label=div;e.labelFill=div.querySelector('.e-bar i');}
function spawnWave(n){currentWave=n;boss=null;enemies.splice(0,enemies.length);ui['enemy-labels'].innerHTML='';ui['boss-panel'].classList.toggle('hidden',n!==3);if(n===1){createEnemy('mob',-.5);createEnemy('mob',2.4);createEnemy('mob',4.2);}else if(n===2){for(let i=0;i<4;i++)createEnemy('mob',i*Math.PI/2+.3);}else createEnemy('boss',Math.PI);ui['wave-number'].textContent=['','WAVE I','WAVE II','FLOOR GUARDIAN'][n];showNotice(n===3?'WARNING':'SYSTEM',n===3?'THE WARDEN':'WAVE '+['','I','II'][n],n===3?'FLOOR BOSS APPROACHING':'HOSTILES DETECTED',n===3?'rose':'');updateHud();}
function showNotice(kicker,text,sub,cls=''){ui.notice.className='notice '+cls;ui['notice-kicker'].textContent=kicker;ui['notice-text'].textContent=text;ui['notice-sub'].textContent=sub;void ui.notice.offsetWidth;ui.notice.classList.add('show');noticeTimer=2.8;}
function toast(title,msg){const t=ui.toast;t.querySelector('span').textContent=title;t.querySelector('b').textContent=msg;t.classList.remove('hidden');toastTimer=2.2;}
function damageText(text,x,y,type=''){const el=document.createElement('div');el.className='dmg '+type;el.textContent=text;el.style.left=`${x}px`;el.style.top=`${y}px`;ui['damage-layer'].appendChild(el);setTimeout(()=>el.remove(),900);}
function project(v){const p=v.clone().project(camera);return{x:(p.x*.5+.5)*innerWidth,y:(-.5*p.y+.5)*innerHeight,z:p.z};}
function updateHud(){const pct=player.hp/player.maxHp*100;ui['hp-fill'].style.width=pct+'%';ui['hp-text'].textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui['stamina-fill'].style.width=player.stamina+'%';ui['enemy-count'].textContent=`${enemies.filter(e=>!e.dead).length} REMAIN`;ui['boss-panel'].classList.toggle('hidden',!boss||boss.dead);if(boss){const bp=boss.hp/boss.maxHp*100;ui['boss-fill'].style.width=bp+'%';ui['boss-hp-text'].textContent=`${Math.ceil(boss.hp)} / ${boss.maxHp}`;ui['boss-phase-label'].textContent=boss.phase===2?'PHASE II':'PHASE I';ui['boss-panel'].classList.toggle('phase-two',boss.phase===2);}
 const charge=Math.min(player.charge,100);ui['skill-ring'].style.strokeDashoffset=276.5*(1-charge/100);ui['skill-orb'].classList.toggle('ready',charge>=100);ui['skill-hint'].textContent=charge>=100?'READY — PRESS Q':`CHARGING — ${Math.floor(charge)}%`;ui['combo-number'].textContent=player.combo;ui['combo-panel'].classList.toggle('show',player.combo>1&&player.comboTime>0);ui['lock-reticle'].classList.toggle('hidden',!lockTarget);if(lockTarget){const p=project(lockTarget.group.position.clone().add(new THREE.Vector3(0,1.4,0)));ui['lock-reticle'].style.left=p.x+'px';ui['lock-reticle'].style.top=p.y+'px';}
}

