ui['lock-reticle'].style.top=p.y+'px';}
}
function nearestEnemy(max=30){let best=null,d=max;for(const e of enemies){if(e.dead)continue;const n=player.group.position.distanceTo(e.group.position);if(n<d){best=e;d=n;}}return best;}
function hitEnemy(e,power=28,crit=false){if(!e||e.dead)return;const dmg=power*(crit?1.65:1);e.hp=Math.max(0,e.hp-dmg);e.stun=.3;e.flash=.14;damageDone+=Math.round(dmg);player.charge=Math.min(100,player.charge+(e.kind==='boss'?2.4:7));player.combo++;player.comboTime=2.2;maxCombo=Math.max(maxCombo,player.combo);const p=project(e.group.position.clone().add(new THREE.Vector3(0,2.1,0)));damageText(`${crit?'✦ ':''}${Math.round(dmg)}`,p.x,p.y,crit?'crit':'');e.group.traverse(o=>{if(o.isMesh)o.material.emissive?.setHex(0x55dff2);});if(e.hp<=0){e.dead=true;e.label?.remove();scene.remove(e.group);if(e===lockTarget)lockTarget=null;toast('SYSTEM',e.kind==='boss'?'Guardian defeated':'Hostile eliminated');if(enemies.every(x=>x.dead)){if(currentWave<3){setTimeout(()=>{if(playing&&!paused)spawnWave(currentWave+1);},1300);}else setTimeout(()=>endGame(true),1200);}}updateHud();}
function attack(){if(!playing||paused||player.attackCd>0)return;player.attackCd=.36;player.group.userData.swing=.28;const target=lockTarget&&!lockTarget.dead?lockTarget:nearestEnemy(5.3);if(target){const delta=target.group.position.clone().sub(player.group.position);if(delta.length()<5.8){player.group.rotation.y=Math.atan2(delta.x,delta.z);hitEnemy(target,24+Math.random()*12,Math.random()<.14);}}}
function useSkill(){if(!playing||paused)return;if(player.charge<100){toast('DUAL ARTS',`${Math.floor(player.charge)}% CHARGED`);return;}player.charge=0;player.attackCd=1.2;player.group.userData.swing=.8;const targets=enemies.filter(e=>!e.dead).sort((a,b)=>a.group.position.distanceTo(player.group.position)-b.group.position.distanceTo(player.group.position)).slice(0,3);if(!targets.length)return;showNotice('DUAL ARTS','STARBURST STREAM','EIGHT-HIT FINISHER','gold');let i=0;const strike=()=>{if(!playing)return;const e=targets[i%targets.length];if(e&&!e.dead){const d=e.group.position.clone().sub(player.group.position);player.group.rotation.y=Math.atan2(d.x,d.z);hitEnemy(e,31,true);}i++;if(i<8)setTimeout(strike,100);};strike();}
function dash(){if(!playing||paused||player.dashCd>0||player.stamina<22)return;player.dashCd=.8;player.stamina-=22;player.invuln=.48;const forward=new THREE.Vector3();camera.getWorldDirection(forward);forward.y=0;forward.normalize();const right=new THREE.Vector3().crossVectors(forward,new THREE.Vector3(0,1,0)).normalize();let dx=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+joystick.x;let dz=(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0)-joystick.y;let dir=right.multiplyScalar(dx).add(forward.multiplyScalar(-dz));if(dir.lengthSq()<.05)dir=forward;dir.normalize();player.group.position.addScaledVector(dir,4.7);player.group.position.x=clamp(player.group.position.x,-23,23);player.group.position.z=clamp(player.group.position.z,-23,23);player.group.rotation.y=Math.atan2(dir.x,dir.z);}
function hurt(amount){if(player.invuln>0||!playing)return;player.hp=Math.max(0,player.hp-amount);player.invuln=.65;hitsTaken++;ui['hit-vignette'].classList.remove('flash');void ui['hit-vignette'].offsetWidth;ui['hit-vignette'].classList.add('flash');damageText(`-${amount}`,innerWidth/2+40,innerHeight/2+35,'player');updateHud();if(player.hp<=0)endGame(false);}
