function drawPortrait(){const c=ui.portrait,ctx=c.getContext('2d');const g=ctx.createLinearGradient(0,0,128,128);g.addColorStop(0,'#1c4960');g.addColorStop(1,'#070d18');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);ctx.strokeStyle='rgba(110,244,255,.35)';ctx.lineWidth=2;ctx.strokeRect(7,7,114,114);ctx.fillStyle='#111721';ctx.beginPath();ctx.ellipse(64,68,31,42,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e2bfa5';ctx.beginPath();ctx.ellipse(64,57,23,29,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#131821';ctx.beginPath();ctx.moveTo(40,52);ctx.lineTo(45,24);ctx.lineTo(60,37);ctx.lineTo(84,19);ctx.lineTo(90,52);ctx.lineTo(78,43);ctx.lineTo(64,48);ctx.lineTo(49,43);ctx.closePath();ctx.fill();ctx.fillStyle='#52d8ec';ctx.fillRect(52,57,6,2);ctx.fillRect(70,57,6,2);ctx.fillStyle='#151c26';ctx.fillRect(43,94,42,34);ctx.strokeStyle='#d3b373';ctx.beginPath();ctx.moveTo(24,118);ctx.lineTo(104,40);ctx.stroke();}
function drawMinimap(){const c=ui.minimap,ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='rgba(111,225,245,.25)';ctx.beginPath();ctx.arc(w/2,h/2,104,0,Math.PI*2);ctx.stroke();for(const e of enemies){if(e.dead)continue;const x=w/2+e.group.position.x*3.6,y=h/2+e.group.position.z*3.6;ctx.fillStyle=e.kind==='boss'?'#ff536f':'#ff829a';ctx.beginPath();ctx.arc(x,y,e.kind==='boss'?6:4,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#72f1ff';ctx.beginPath();ctx.arc(w/2+player.group.position.x*3.6,h/2+player.group.position.z*3.6,4,0,Math.PI*2);ctx.fill();}
function updateLabels(){for(const e of enemies){if(e.dead)continue;const p=project(e.group.position.clone().add(new THREE.Vector3(0,2.4,0)));e.label.style.left=`${p.x}px`;e.label.style.top=`${p.y}px`;e.label.style.opacity=p.z<1&&p.z>-1?'1':'0';e.labelFill.style.width=`${e.hp/e.maxHp*100}%`;e.label.classList.toggle('locked',e===lockTarget);}}
function formatTime(seconds){const s=Math.floor(seconds);return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function pauseGame(){if(!playing)return;paused=true;ui['pause-screen'].classList.remove('hidden');ui['pause-wave'].textContent=`${['','I','II','III'][currentWave]} / III`;ui['pause-time'].textContent=formatTime(elapsed);document.exitPointerLock?.();}
function resumeGame(){paused=false;ui['pause-screen'].classList.add('hidden');}
function endGame(win){playing=false;paused=false;document.exitPointerLock?.();ui['pause-screen'].classList.add('hidden');ui['end-screen'].classList.remove('hidden');ui['end-kicker'].textContent=win?'FLOOR 75 // GATE OPEN':'SYSTEM FAILURE';ui['end-title'].textContent=win?'FLOOR CLEARED':'YOU HAVE FALLEN';ui['end-copy'].textContent=win?'The gate to the next floor has opened.':'Aincrad waits for your next attempt.';ui['end-time'].textContent=formatTime(elapsed);ui['end-combo'].textContent=maxCombo;ui['end-damage'].textContent=damageDone;ui['end-hits'].textContent=hitsTaken;ui['end-rank'].querySelector('b').textContent=win?(elapsed<100&&hitsTaken<5?'S':elapsed<180?'A':'B'):'—';}
function startGame(){player.hp=100;player.stamina=100;player.charge=0;player.combo=0;player.comboTime=0;player.attackCd=0;player.dashCd=0;player.invuln=0;player.group.position.set(0,0,6);elapsed=damageDone=hitsTaken=maxCombo=0;lockTarget=null;enemies.forEach(e=>{scene.remove(e.group);e.label?.remove();});enemies.length=0;ui['end-screen'].classList.add('hidden');ui['title-screen'].classList.add('hidden');ui['hud'].classList.remove('hidden');playing=true;paused=false;spawnWave(1);updateHud();renderer.domElement.requestPointerLock?.();}
function returnTitle(){playing=false;paused=false;ui['end-screen'].classList.add('hidden');ui['hud'].classList.add('hidden');ui['title-screen'].classList.remove('hidden');document.exitPointerLock?.();}
let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-last)/1000);last=now;if(playing&&!paused){elapsed+=dt;player.attackCd=Math.max(0,player.attackCd-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.invuln=Math.max(0,player.invuln-dt);player.comboTime=Math.max(0,player.comboTime-dt);movePlayer(dt);updateEnemies(dt);if(player.group.userData.swing>0){player.group.userData.swing-=dt;player.group.rotation.y+=Math.sin(now*.04)*.012;}if(Math.floor(elapsed)%1===0){}ui['run-timer'].textContent=formatTime(elapsed);if(noticeTimer>0){noticeTimer-=dt;if(noticeTimer<=0)ui.notice.classList.remove('show');}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.add('hidden');}updateCamera(dt);updateLabels();drawMinimap();updateHud();}else{updateCamera(dt);}renderer.render(scene,camera);}
requestAnimationFrame(frame);drawPortrait();
const loaderStart=performance.now();function finishLoad(){const n=clamp((performance.now()-loaderStart)/1150*100,0,100);ui['loader-bar'].style.width=n+'%';ui['loader-percent'].textContent=Math.floor(n)+'%';ui['loader-status'].textContent=n<70?'BUILDING AINCRAD INSTANCE':'CALIBRATING DUAL BLADES';if(n<100)requestAnimationFrame(finishLoad);else setTimeout(()=>{ui.loader.classList.add('done');ui['title-screen'].classList.remove('hidden');ui['start-btn'].disabled=false;},220);}requestAnimationFrame(finishLoad);

